'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
for(const n of ['core','solitaire','table','hongkong','american','coach','learn','practice','path'])require('../js/'+n+'.js');
const M=globalThis.Mahjong,H=s=>(s||'').split(' ').filter(Boolean).map(M.core.makeTile);
const context={seat:0,prevailing:0,selfDraw:false,flowers:[],flowersEnabled:false,source:'draw',lastWall:false,heavenly:false,earthly:false,sevenPairs:false};
// Expected values were calculated by hand from the documented profile, not generated by the engine.
for(const f of require('./fixtures/hk-scores.json'))test('HK score fixture: '+f.id,()=>{
 const tiles=H(f.hand),c={...context,...f,flowers:H(f.flowers)};
 const analyses=[...M.hongkongTest.partitions(tiles).map(p=>M.hongkongTest.extendedScore(p,[],tiles,c)),...M.hongkongTest.specialHands(tiles,[],c)];
 const a=analyses.sort((a,b)=>b.fan-a.fan)[0];assert.ok(a);assert.equal(a.fan,f.fan);if(f.qualifyingFan!==undefined)assert.equal(a.qualifyingFan,f.qualifyingFan);
});
const hk=()=>{const g=new M.HongKongTable({hkProfile:'atelier',flowers:false});g.lastSource='draw';g.discardCount=4;g.interrupted=true;return g;};
function am(){const g=new M.AmericanTable();g.phase='charleston';return g;}
function pass(g,blind=[0,0,0,0]){for(let i=0;i<4;i++)g.submitPass(i,g.players[i].hand.filter(t=>t.type!=='j').slice(0,g.passCount(i)-blind[i]).map(t=>t.id),blind[i]);}
function ids(g){return [...g.wall,...g.players.flatMap(p=>[...p.hand,...p.flowers,...p.discards,...p.melds.flatMap(m=>m.tiles)])].map(t=>t.id).sort((a,b)=>a-b);}
test('impossible fifth copies and malformed exposed sets cannot validate as wins',()=>{
 assert.equal(M.hongkongTest.partitions(H('b1 b1 b1 b1 b1 b1 d2 d2 d2 c3 c3 c3 we we')).length,0);
 assert.equal(M.americanTest.winningPatterns(H('b1 b1 b1 b1 b1 b1 d2 d2 d2 c3 c3 c3 we we')).length,0);
 assert.equal(M.hongkongTest.partitions(H('b1 b2 b3 d4 d5 d6 c7 c8 c9 we we'),[{kind:'chow',type:'b1',tiles:H('b1 b2 b2')}]).length,0);
});
test('Kong replacement preserves counts and four Kongs occupy four meld slots',()=>{
 const g=hk();g.players[0].hand=H('we we');g.players[0].melds=['b1','d2','c3','b8'].map(type=>({kind:'kong',type,tiles:H(Array(4).fill(type).join(' ')),concealed:false}));
 assert.equal(g.winAnalysis(0).fan,10);assert.equal(g.players[0].hand.length+g.players[0].melds.flatMap(m=>m.tiles).length,18);
});
test('declining a qualifying HK win blocks that discarded type until own draw, not other waits',()=>{
 const g=hk();g.players[1].hand=H('b2 b3 d4 d5 d6 c7 c8 c9 dr dr dr we we');g.players[2].hand=[];g.players[3].hand=[];g.players[0].hand=H('b1');g.discard(0,g.players[0].hand[0].id);
 // A second eligible claimant keeps the window open; passing alone must already mark the missed win.
 g.claimQueue.push(2);g.submitClaim(1,'pass');assert.equal(g.winAnalysis(1,M.core.makeTile('b1'),false),null);assert.ok(g.winAnalysis(1,M.core.makeTile('b4'),false));
 const before=g.players[1].hand.length;g.drawTile(1);g.players[1].hand.splice(g.players[1].hand.findIndex(t=>t.id===g.lastDraw.id),1);assert.equal(g.players[1].hand.length,before);assert.ok(g.winAnalysis(1,M.core.makeTile('b1'),false));
});
test('invalid claim cannot change missed-win state',()=>{const g=hk();g.players[1].hand=H('b2 b3 d4 d5 d6 c7 c8 c9 dr dr dr we we');g.players[0].hand=H('b1');g.discard(0,g.players[0].hand[0].id);assert.throws(()=>g.submitClaim(1,'invented'));assert.equal(g.missedWins[1].size,0);});
test('HK Thirteen Orphans wins priority over a nearer ordinary winning claim',()=>{
 const g=hk();g.players[0].hand=H('b1');g.players[1].hand=H('b2 b3 d4 d5 d6 c7 c8 c9 dr dr dr we we');g.players[2].hand=H('b9 d1 d9 c1 c9 we ws ww wn dr dg dw we');g.players[3].hand=[];
 g.discard(0,g.players[0].hand[0].id);g.submitClaim(1,'win');g.submitClaim(2,'win');assert.equal(g.winner,2);
});
test('only the discard immediately following the last wall draw gets last-discard bonus',()=>{
 const g=hk();g.wall=[];g.players[0].hand=H('d9');g.players[1].hand=[];g.players[2].hand=[];g.players[3].hand=[];g.lastSource='claim';g.discard(0,g.players[0].hand[0].id);assert.equal(g.players[0].discards.length,1);
 // Check attribution at a still-open actual window.
 const x=hk();x.wall=[];x.lastSource='claim';x.players[0].hand=H('b3');x.players[1].hand=H('b1 b2 d4 d5 d6 c7 c8 c9 dr dr dr we we');x.players[2].hand=[];x.players[3].hand=[];x.discard(0,x.players[0].hand[0].id);assert.equal(x.winAnalysis(1,x.lastDiscard.tile,false).fan,1);
});
test('American dealt win precedes Charleston and pays self-picked value',()=>{
 const g=new M.AmericanTable();g.players[0].hand=H('b1 b1 b1 d2 d2 d2 c3 c3 c3 dr dr dr we we');assert.throws(()=>g.beginCharleston(),/completed opening/);assert.ok(g.canDeclareWin(0));assert.equal(g.canDeclareWin(1),null);assert.deepEqual(g.declareWin(0).payments,[300,-100,-100,-100]);
});
test('American nonwinning dealer starts passing without an extra draw; round boundary permits dealer win',()=>{
 const g=new M.AmericanTable();g.players[0].hand=H('b1 b2 b3 b4 b5 b6 d1 d2 d3 c4 c5 c6 we dr');const n=g.wall.length;g.beginCharleston();assert.equal(g.phase,'charleston');assert.equal(g.wall.length,n);
 g.players[0].hand=H('b1 b1 b1 d2 d2 d2 c3 c3 c3 dr dr dr we we');g.offerPassingWin('secondChoice');assert.equal(g.phase,'passingWin');assert.ok(g.canDeclareWin(0));g.continuePassing();assert.equal(g.phase,'secondChoice');
});
test('all-three-blind final right ends Charleston without courtesy, first left requires a real packet',()=>{
 for(const index of [2,5]){const g=am();g.charIndex=index;if(index===5)g.passRoute.push({name:'Left',offset:3},{name:'Across',offset:2},{name:'Right',offset:1});const before=ids(g);pass(g,[3,3,3,3]);assert.deepEqual(ids(g),before);assert.equal(g.phase,index===2?'blindDeadlock':'discard');if(index===2){g.retryBlindPass();assert.equal(g.phase,'charleston');assert.equal(g.charSeat,0);}}
});
test('ordinary across pass delivers each physical packet once to its opposite seat',()=>{
 const g=am();g.charIndex=1;const packets=g.players.map(p=>p.hand.filter(t=>t.type!=='j').slice(0,3).map(t=>t.id)),before=ids(g);pass(g);for(let i=0;i<4;i++)assert.ok(packets[i].every(id=>g.players[(i+2)%4].hand.some(t=>t.id===id)));assert.deepEqual(ids(g),before);
});
test('American claims offer different legal natural/Joker mixes',()=>{const g=am();g.players[1].hand=H('b1 b1 b1 j j d2 d2');const opts=g.claimOptions(1,M.core.makeTile('b1')).filter(o=>o.kind==='pung');assert.deepEqual(opts.map(o=>o.use.filter(id=>g.players[1].hand.find(t=>t.id===id).type==='j').length),[0,1,2]);});
test('new exposure can change size and mix, but keeps claimed tile and locks after discard',()=>{
 const g=am();g.phase='discard';g.current=0;g.players[0].hand=H('b1');g.players[1].hand=H('b1 b1 j d2 d2 c3 c3 c3 dr dr we we c9');g.players[2].hand=[];g.players[3].hand=[];g.discard(0,g.players[0].hand[0].id);g.submitClaim(1,'set-3');
 const material=ids(g),claimed=g.players[1].melds[0].claimedTileId;const option=g.adjustmentOptions(1).find(o=>o.size===4);assert.ok(option);g.adjustExposure(1,option.ids);assert.equal(g.players[1].melds[0].kind,'kong');assert.deepEqual(ids(g),material);assert.ok(g.players[1].melds[0].tiles.some(t=>t.id===claimed));assert.throws(()=>g.adjustExposure(1,option.ids.filter(id=>id!==claimed)));
 g.discard(1,g.players[1].hand[0].id);assert.deepEqual(g.adjustmentOptions(1),[]);assert.throws(()=>g.adjustExposure(1,option.ids));
});
test('Joker exchange locks provisional exposure and requires a drawn/claimed turn',()=>{
 const g=am();g.phase='discard';g.current=0;g.players[0].hand=H('c5');g.players[1].melds=[{kind:'pung',type:'c5',tiles:H('c5 c5 j')}];g.lastSource='deal';assert.throws(()=>g.exchangeJoker(0,1,0),/after drawing/);g.lastSource='draw';g.editableExposure={seat:0,index:0};g.exchangeJoker(0,1,0);assert.equal(g.editableExposure,null);
});
test('Solitaire free rule is independently checked through a full clearing witness for each layout',()=>{
 function free(p,tiles){const above=tiles.some(t=>t.z>p.z&&t.x===p.x&&t.y===p.y),left=tiles.some(t=>t.z===p.z&&t.y===p.y&&t.x===p.x-1),right=tiles.some(t=>t.z===p.z&&t.y===p.y&&t.x===p.x+1);return !above&&!(left&&right);}
 for(const layout of ['portrait','pyramid','garden','bridge']){const positions=M.solitaireTest.coords(layout),deal=M.solitaireTest.assignDeal(positions,M.core.tileset('solitaire'),()=>.5),order=M.solitaireTest.removalOrder(positions,()=>.5);let alive=deal.slice();for(const pair of order){const [a,b]=pair.map(id=>alive.find(t=>t.id===id));assert.ok(free(a,alive)&&free(b,alive));assert.equal(M.core.matchKey(a.tile.type),M.core.matchKey(b.tile.type));alive=alive.filter(t=>!pair.includes(t.id));}assert.equal(alive.length,0);}
});
test('American pivot rotation preserves player identity, human seat, and score ownership',()=>{
 const g=am();g.rotations=3;g.dealer=3;g.scores=[120,-20,-40,-60];g.endDraw();const n=g.nextHand();assert.equal(n.dealer,1);assert.equal(n.round,1);assert.deepEqual(n.players.map(p=>p.id),[1,0,2,3]);assert.deepEqual(n.scores,[-20,120,-40,-60]);assert.equal(n.players[1].name,'You');assert.equal(n.players[1].bot,false);assert.equal(n.players[0].bot,true);
 n.rotations=7;n.dealer=0;n.endDraw();const third=n.nextHand();assert.equal(third.dealer,2);assert.equal(third.players[2].id,0);assert.equal(third.scores[2],120);
});
test('all final-right blind combinations conserve exact identities and rack lengths',()=>{
 for(let code=0;code<256;code++){const g=am();g.charIndex=5;g.passRoute.push({name:'Left',offset:3},{name:'Across',offset:2},{name:'Right',offset:1});const before=ids(g),sizes=g.players.map(p=>p.hand.length);pass(g,[code%4,(code>>2)%4,(code>>4)%4,(code>>6)%4]);assert.deepEqual(ids(g),before);assert.deepEqual(g.players.map(p=>p.hand.length),sizes);assert.ok((code===255?['discard']:['courtesyChoice','passingWin']).includes(g.phase));}
});
